# arent/pack/make_zip.ps1 - build the self-sufficient archive for the RTX 4060 machine.
#
# Run through pack_4060.bat (or directly): the result is one zip that unpacks anywhere.
# The unpacked folder holds the launchers (AUTO.bat / START_HERE.bat) at its root and a
# "server" subfolder with the whole project, so paths inside the .bat files
# (<root>\server\arent\setup.bat) line up. Everything training needs (arenas, live
# snapshots, datasets, checkpoints) is already inside.
#
# What never goes in: .venv (machine specific), build/dist (regenerated by build_exe.bat),
# logs, __pycache__, .env (contains the DeepSeek key), .pip-tmp, wheels.
param(
    [string]$OutDir = "",
    [string]$Name = "",
    [switch]$Lean                     # code and config only: no datasets, no checkpoints
)
$ErrorActionPreference = "Stop"

$arent = Split-Path $PSScriptRoot -Parent
$server = Split-Path $arent -Parent
$moduleRoot = Split-Path (Split-Path (Split-Path $server -Parent) -Parent) -Parent
if (-not $Name) { $Name = "arent4060-" + (Get-Date).ToString("yyyyMMdd") }
if (-not $OutDir) { $OutDir = Join-Path $moduleRoot "temp" }

$stage = Join-Path $env:TEMP ($Name + "-stage")
$stageServer = Join-Path $stage "server"
$zip = Join-Path $OutDir ($Name + ".zip")
$log = @()

if (Test-Path $stage) { Remove-Item $stage -Recurse -Force }
New-Item -ItemType Directory -Force -Path $stageServer | Out-Null
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null

$xd = @("$server\.venv", "$arent\build", "$arent\dist", "$arent\.pip-tmp",
        "$server\logs", ".venv", "__pycache__", ".pytest_cache", "wheels")
if ($Lean) { $xd += "$arent\data\samples", (Join-Path $arent "runs") }
& robocopy $server $stageServer /E /NFL /NDL /NJH /NJS /NP /XD $xd /XF .env | Out-Null
if ($LASTEXITCODE -ge 8) { throw "robocopy failed with code $LASTEXITCODE" }
$global:LASTEXITCODE = 0

# the launchers go to the archive ROOT, next to the server folder
foreach ($file in "START_HERE.txt", "START_HERE.bat", "RUN_ALL.bat", "AUTO.bat", "AB.bat", "RL.bat") {
    Copy-Item (Join-Path $PSScriptRoot $file) (Join-Path $stage $file)
}

$must = @("START_HERE.bat", "START_HERE.txt", "RUN_ALL.bat", "AUTO.bat", "AB.bat", "RL.bat",
          "server\server.py", "server\run_server.bat", "server\requirements.txt",
          "server\points.json", "server\arent\main.py", "server\arent\cli.py",
          "server\arent\train.py", "server\arent\bench.py", "server\arent\capture.py",
          "server\arent\evaluate.py", "server\arent\rl.py", "server\arent\rollout.py",
          "server\arent\env.py", "server\arent\torch_rl.py",
          "server\arent\setup.bat", "server\arent\arent.bat", "server\arent\build_exe.bat",
          "server\arent\config.json", "server\arent\requirements.txt",
          "server\arent\pack\verify_zip.ps1",
          "server\arent\pack\run_logged.ps1",
          "server\arent\pack\no_quickedit.ps1",
          "server\arent\data\payloads\arena1_live.json",
          "server\planner\service.py", "server\playground\arena.py")
foreach ($rel in $must) {
    if (-not (Test-Path (Join-Path $stage $rel))) { throw "pack: missing $rel" }
}

if (Test-Path $zip) { Remove-Item $zip -Force }
Compress-Archive -Path (Join-Path $stage "*") -DestinationPath $zip -CompressionLevel Optimal

Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive = [System.IO.Compression.ZipFile]::OpenRead($zip)
$entries = $archive.Entries
$log += "zip       : $zip"
$log += ("size      : {0:N0} bytes ({1:N2} MB)" -f (Get-Item $zip).Length,
         ((Get-Item $zip).Length / 1MB))
$log += "entries   : $($entries.Count)"
$leak = $entries | Where-Object { $_.FullName -match "\.env$|/build/|/dist/|\.venv/|__pycache__|/logs/|\.pip-tmp/" }
$log += "leaks     : $(if ($leak) { ($leak | ForEach-Object FullName) -join ", " } else { "none" })"
$serverFolder = $entries | Where-Object { $_.FullName -replace "\\", "/" -like "server/*" }
$log += "server/    : $(if ($serverFolder) { 'present' } else { 'MISSING - broken layout' })"
foreach ($group in @("data/samples", "data/payloads", "runs", "tests")) {
    $found = $entries | Where-Object { $_.FullName -replace "\\", "/" -like "*$group*" }
    $bytes = ($found | Measure-Object -Property Length -Sum).Sum
    $log += ("{0,-14}: {1} file(s), {2:N0} bytes" -f $group, $found.Count, $bytes)
}
$archive.Dispose()
Remove-Item $stage -Recurse -Force

$log += "next      : copy the zip to the 4060 machine, unpack the WHOLE thing, double-click AUTO.bat"
$text = $log -join "`r`n"
[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
Write-Output $text
# report goes next to the zip (in temp), never into the repository
[System.IO.File]::WriteAllText((Join-Path $OutDir "last_pack.txt"), $text,
                               [System.Text.UTF8Encoding]::new($false))
